const input = $json.body ?? $json;
const question = String(input.message ?? input.question ?? '').trim();
const origin = String($json.headers?.origin ?? '').trim();
const forwardedFor = String($json.headers?.['x-forwarded-for'] ?? '').split(',')[0].trim();
const ip = forwardedFor || String($json.headers?.['x-real-ip'] ?? $json.headers?.['cf-connecting-ip'] ?? 'unknown');
const staticData = $getWorkflowStaticData('global');
const now = Date.now();
const windowMs = 60 * 60 * 1000;
const maxRequests = Number($env.PORTFOLIO_CHAT_MAX_REQUESTS_PER_HOUR || 20);
staticData.rateLimit = staticData.rateLimit || {};
staticData.rateLimit[ip] = (staticData.rateLimit[ip] || []).filter((timestamp) => now - timestamp < windowMs);

if (staticData.rateLimit[ip].length >= maxRequests) {
  return [{ json: { valid: false, statusCode: 429, answer: 'Llegaste al límite de preguntas por ahora. Intenta nuevamente más tarde.' } }];
}

if (!question) {
  return [{ json: { valid: false, statusCode: 400, answer: 'Escribí una pregunta sobre Juan Gabriel, su experiencia, proyectos o habilidades.' } }];
}

if (question.length > 500) {
  return [{ json: { valid: false, statusCode: 413, answer: 'La pregunta es demasiado larga. Intenta resumirla en menos de 500 caracteres.' } }];
}

staticData.rateLimit[ip].push(now);
const normalizedQuestion = question
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9ñ\s]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

return [{
  json: {
    valid: true,
    statusCode: 200,
    origin,
    ip,
    question,
    normalizedQuestion
  }
}];

const row = $json;
const question = row.question || $('Validate + Normalize Question').item.json.question;
const normalizedQuestion = row.normalized_question || $('Validate + Normalize Question').item.json.normalizedQuestion;

if (row.direct_answer) {
  return [{
    json: {
      answer: row.direct_answer,
      statusCode: 200,
      source: row.answer_source || 'database',
      question,
      normalizedQuestion
    }
  }];
}

const facts = row.facts_json || {};
const factDetails = row.fact_details_json || {};
const experience = row.experience_json || [];
const projects = row.projects_json || [];
const education = row.education_json || [];

const dbContext = JSON.stringify({ facts, factDetails, experience, projects, education }, null, 2);
const systemPrompt = `Sos el asistente del portafolio profesional de Juan Gabriel Alfonso Rojas.
Respondé en español, claro y breve.
Usá únicamente el contexto estructurado proveniente de PostgreSQL.
Podés responder sobre perfil, experiencia, proyectos, educación, habilidades, contacto, IA aplicada, agentes IA, RAG/NotebookLM, monitoreo de infraestructura Linux, análisis de logs y formación Anthropic de Juan.
Si preguntan por datos exactos, respetá los facts y factDetails; no calcules libremente.
Si preguntan por certificaciones o cursos, usá sólo los enlaces y estado presentes en factDetails o education.
Si la pregunta no tiene relación con Juan o su portafolio, respondé: "Puedo ayudarte sólo con información profesional de Juan Gabriel Alfonso Rojas y su portafolio."
No inventes datos, empresas, títulos, certificaciones, enlaces ni proyectos.
No incluyas etiquetas como <assistant>, </assistant>, <user>, <system> ni tokens especiales.
Respondé sólo el texto final visible para el visitante.

Contexto PostgreSQL:
${dbContext}`;

return [{
  json: {
    valid: true,
    question,
    normalizedQuestion,
    systemPrompt,
    source: 'ai'
  }
}];

let answer =
  $json.text ||
  $json.output ||
  $json.answer ||
  $json.choices?.[0]?.message?.content ||
  'No pude generar una respuesta en este momento. Intenta de nuevo.';

answer = String(answer)
  .replace(/<\/?assistant>/gi, '')
  .replace(/<\/?user>/gi, '')
  .replace(/<\/?system>/gi, '')
  .replace(/<\|.*?\|>/g, '')
  .trim();

return [
  {
    json: {
      answer,
      statusCode: 200,
    },
  },
];
